  ('m4-12', 'quiz', 'Cuestionario 5', 4, 3, false, 'activo', 'es', 15, '{"preguntas": [{"texto": "¿Cuál es el aspecto más importante de la fortaleza?", "opciones": ["La audacia", "La resistencia", "La intransigencia", "El sacrificio propio"], "correcta": 1}, {"texto": "¿Qué requiere más energía?", "opciones": ["La resistencia", "La audacia", "La filantropía", "El trabajo duro"], "correcta": 0}, {"texto": "¿Qué virtud está arraigada en la resistencia?", "opciones": ["La paciencia", "La fidelidad", "La perseverancia", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "La «audacia» sin prudencia ni justicia no es audacia; es…", "opciones": ["Demencia", "Odio", "Venganza", "Todo lo anterior"], "correcta": 3}]}'::jsonb),
  ('m4-concl-3', 'conclusion_modulo', 'Resumen: Fortaleza', 4, 3, false, 'activo', 'es', 16, '{"modulo_numero": 3, "modulo_titulo": "Practicar la fortaleza", "aprendizajes": ["Resistencia y audacia: los dos aspectos de la fortaleza", "La audacia sin prudencia se convierte en temeridad", "La paciencia, la fidelidad y la perseverancia nacen de la resistencia"], "ejercicios_evaluables": [{"id": "m4-12", "label": "Cuestionario 5"}]}'::jsonb),
