  ('m4-15', 'test_profundo', 'Reto: Fortaleza', 4, 4, false, 'activo', 'es', 18, '{"caratula_titulo": "Reto: Fortaleza", "resumen_ficha": "¿Mantengo el rumbo en la adversidad?", "prioridad_ficha": 3, "descripcion": "Busca un momento tranquilo para realizar este ejercicio. Reflexiona con sinceridad sobre cada afirmación.\n\nNo hay respuestas correctas ni incorrectas: este autoexamen es una herramienta para tu crecimiento personal.", "preguntas": [{"texto": "Formo mi conciencia mediante una búsqueda sincera y sistemática de la verdad.", "placeholder": "¿Dedicas tiempo a buscar la verdad de forma sistemática?"}, {"texto": "Soy coherente en mi comportamiento. No sucumbo a la tentación de lo «culturalmente correcto».", "placeholder": "¿Actúas según tus principios o según lo que esperan de ti?"}, {"texto": "Mis colegas de trabajo tienen claro cuáles son los ideales que defiendo.", "placeholder": "¿Las personas de tu entorno conocen tus convicciones?"}, {"texto": "No me preocupo de lo que los demás puedan pensar o decir de mí.", "placeholder": "¿El qué dirán influye en tus decisiones?"}, {"texto": "Mantengo mi conciencia íntegra incluso bajo amenaza de muerte.", "placeholder": "¿Hay algo por lo que no transigirías?"}, {"texto": "No actúo inmoralmente escudándome en la inmoralidad general.", "placeholder": "¿Has justificado alguna vez una acción incorrecta con el argumento de que «todo el mundo lo hace»?"}, {"texto": "Asumo riesgos. Supero el miedo al posible fracaso.", "placeholder": "¿El miedo al fracaso te frena o te motiva?"}, {"texto": "Mantengo el rumbo, también en las contradicciones.", "placeholder": "¿Eres capaz de mantener tu rumbo cuando las circunstancias se ponen en contra?"}, {"texto": "Llevo a cabo todos mis proyectos cuidando de los detalles.", "placeholder": "¿Eres constante en los detalles o tiendes a dejar las cosas a medias?"}, {"texto": "Mi perseverancia no es el resultado de una obstinación fuera de lugar, sino el fruto de una posición de principios ponderada.", "placeholder": "¿Tu perseverancia nace de la convicción o de la terquedad?"}]}'::jsonb),
  ('m4-14', 'quiz', 'Cuestionario 6', 4, 4, false, 'activo', 'es', 19, '{"preguntas": [{"texto": "¿Qué puede aprender un colérico de la virtud de la fortaleza?", "opciones": ["Mantenerse firme en su camino a pesar de la enfermedad y del cansancio", "Superar el miedo a la incertidumbre sobre el futuro", "Terminar lo que ha comenzado, superar la inconsistencia y la frivolidad", "Superar la apatía y el miedo al fracaso, salir de su zona de confort y rutina"], "correcta": 0}, {"texto": "¿Qué puede aprender un melancólico de la virtud de la fortaleza?", "opciones": ["Mantenerse firme en su camino a pesar de la enfermedad y del cansancio", "Superar el miedo a la incertidumbre sobre el futuro", "Terminar lo que ha comenzado, superar la inconsistencia y la frivolidad", "Superar la apatía y el miedo al fracaso, salir de su zona de confort y rutina"], "correcta": 1}, {"texto": "¿Qué puede aprender un sanguíneo de la virtud de la fortaleza?", "opciones": ["Mantenerse firme en su camino a pesar de la enfermedad y del cansancio", "Superar el miedo a la incertidumbre sobre el futuro", "Terminar lo que ha comenzado, superar la inconsistencia y la frivolidad", "Superar la apatía y el miedo al fracaso, salir de su zona de confort y rutina"], "correcta": 2}, {"texto": "¿Qué puede aprender un flemático de la virtud de la fortaleza?", "opciones": ["Mantenerse firme en su camino a pesar de la enfermedad y del cansancio", "Superar el miedo a la incertidumbre sobre el futuro", "Terminar lo que ha comenzado, superar la inconsistencia y la frivolidad", "Superar la apatía y el miedo al fracaso, salir de su zona de confort y rutina"], "correcta": 3}]}'::jsonb),
  ('m4-concl-4', 'conclusion_modulo', 'Resumen: Fortaleza y temperamentos', 4, 4, false, 'activo', 'es', 20, '{"modulo_numero": 4, "modulo_titulo": "La fortaleza y los 4 temperamentos", "aprendizajes": ["Cómo cada temperamento afronta la fortaleza", "Reto personal: resistencia y audacia en tu vida diaria"], "ejercicios_evaluables": [{"id": "m4-14", "label": "Cuestionario 6"}, {"id": "m4-15", "label": "Reto: Fortaleza"}]}'::jsonb),
