  ('m4-17', 'quiz', 'Cuestionario 7', 4, 5, false, 'activo', 'es', 22, '{"preguntas": [{"texto": "El dominio de sí es el hábito de:", "opciones": ["Gestionar las emociones", "Evitar las adicciones", "No expresar la ira en público", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "Las emociones son buenas cuando:", "opciones": ["Generan placer", "Nos impulsan a realizar acciones constructivas", "Son apreciadas por los demás", "Todas las respuestas son correctas"], "correcta": 1}, {"texto": "¿Cómo se puede evaluar la calidad de una emoción?", "opciones": ["Con la razón", "Mediante pruebas", "Con la ayuda de un psicoterapeuta", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "¿Por qué son peligrosas las malas emociones?", "opciones": ["Pueden llevar a la autodestrucción", "Transgreden las normas de decencia", "Pueden provocar úlceras estomacales", "Todas las respuestas son correctas"], "correcta": 0}]}'::jsonb),
  ('m4-concl-5', 'conclusion_modulo', 'Resumen: Dominio de sí', 4, 5, false, 'activo', 'es', 23, '{"modulo_numero": 5, "modulo_titulo": "Practicar el dominio de sí", "aprendizajes": ["El dominio de sí es gestionar las emociones, no reprimirlas", "Las emociones son buenas cuando impulsan acciones constructivas", "La razón es la guía para evaluar la calidad de las emociones"], "ejercicios_evaluables": [{"id": "m4-17", "label": "Cuestionario 7"}]}'::jsonb),
