  ('m4-20', 'test_profundo', 'Reto: Dominio de sí', 4, 6, false, 'activo', 'es', 25, '{"caratula_titulo": "Reto: Dominio de sí", "resumen_ficha": "¿Gestiono mis emociones o ellas me gobiernan?", "prioridad_ficha": 2, "descripcion": "Busca un momento tranquilo para realizar este ejercicio. Reflexiona con sinceridad sobre cada afirmación.\n\nNo hay respuestas correctas ni incorrectas: este autoexamen es una herramienta para tu crecimiento personal.", "preguntas": [{"texto": "Hago lo que debo hacer, no lo que me resulta agradable.", "placeholder": "¿Cómo eliges entre lo cómodo y lo correcto en tu día a día?"}, {"texto": "Hago primero lo importante, no lo urgente.", "placeholder": "¿Priorizas lo verdaderamente importante o te dejas llevar por lo urgente?"}, {"texto": "Dedico tiempo a lo que más importa: mi desarrollo personal, el desarrollo de los demás, la gestión a largo plazo.", "placeholder": "¿A qué dedicas la mayor parte de tu tiempo y energía?"}, {"texto": "Mantengo la paz incluso en aquellas circunstancias que me ponen a prueba.", "placeholder": "¿Cómo reaccionas cuando las circunstancias te presionan?"}, {"texto": "Reacciono con calma y cortesía a la crítica y la oposición, sin alzar la voz ni usar lenguaje vulgar.", "placeholder": "¿Cómo respondes cuando te critican o se oponen a tus ideas?"}, {"texto": "No soy esclavo ni del dinero, ni del poder, ni de la fama, ni del placer.", "placeholder": "¿Hay algo material o inmaterial que te tenga atado?"}, {"texto": "El desprendimiento de las cosas terrenas y la pureza de corazón, mente y cuerpo son las alas que me permiten alcanzar las alturas, como un águila.", "placeholder": "¿Qué te impide volar más alto? ¿Qué necesitarías soltar?"}]}'::jsonb),
  ('m4-19', 'quiz', 'Cuestionario 8', 4, 6, false, 'activo', 'es', 26, '{"preguntas": [{"texto": "¿Qué puede aprender un colérico de la virtud del dominio de sí?", "opciones": ["Superar la ira injusta y el orgullo", "Superar el pesimismo, la ansiedad, la tristeza, el espíritu crítico, la susceptibilidad", "Superar la hipersensibilidad a los estímulos y tentaciones externas", "Superar la apatía y fortalecer sus emociones"], "correcta": 0}, {"texto": "¿Qué puede aprender un melancólico de la virtud del dominio de sí?", "opciones": ["Superar la ira injusta y el orgullo", "Superar el pesimismo, la ansiedad, la tristeza, el espíritu crítico, la susceptibilidad", "Superar la hipersensibilidad a los estímulos y tentaciones externas", "Superar la apatía y fortalecer sus emociones"], "correcta": 1}, {"texto": "¿Qué puede aprender un sanguíneo de la virtud del dominio de sí?", "opciones": ["Superar la ira injusta y el orgullo", "Superar el pesimismo, la ansiedad, la tristeza, el espíritu crítico, la susceptibilidad", "Superar la hipersensibilidad a los estímulos y tentaciones externas", "Superar la apatía y fortalecer sus emociones"], "correcta": 2}, {"texto": "¿Qué puede aprender un flemático de la virtud del dominio de sí?", "opciones": ["Superar la ira injusta y el orgullo", "Superar el pesimismo, la ansiedad, la tristeza, el espíritu crítico, la susceptibilidad", "Superar la hipersensibilidad a los estímulos y tentaciones externas", "Superar la apatía y fortalecer sus emociones"], "correcta": 3}]}'::jsonb),
  ('m4-concl-6', 'conclusion_modulo', 'Resumen: Dominio de sí y temperamentos', 4, 6, false, 'activo', 'es', 27, '{"modulo_numero": 6, "modulo_titulo": "El dominio de sí y los 4 temperamentos", "aprendizajes": ["Cómo cada temperamento afronta el dominio de sí", "Reto personal: gestión emocional en tu vida diaria"], "ejercicios_evaluables": [{"id": "m4-19", "label": "Cuestionario 8"}, {"id": "m4-20", "label": "Reto: Dominio de sí"}]}'::jsonb),
