  ('m4-22', 'quiz', 'Cuestionario 9', 4, 7, false, 'activo', 'es', 29, '{"preguntas": [{"texto": "¿Cuál es la virtud social por excelencia?", "opciones": ["La prudencia", "La fortaleza", "La justicia", "Todo lo anterior"], "correcta": 2}, {"texto": "El aspecto pasivo de la justicia es…", "opciones": ["La veracidad, la simplicidad", "La empatía, la amistad", "El amor, la misericordia", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "El aspecto activo de la justicia es…", "opciones": ["La laboriosidad", "El cuidado de la vida del hogar", "La virtud de la ciudadanía", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "Una persona justa es una persona…", "opciones": ["Abierta y comunicativa", "Misericordiosa", "Que construye el bien común", "Todas las respuestas son correctas"], "correcta": 3}]}'::jsonb),
  ('m4-concl-7', 'conclusion_modulo', 'Resumen: Justicia', 4, 7, false, 'activo', 'es', 30, '{"modulo_numero": 7, "modulo_titulo": "Practicar la justicia", "aprendizajes": ["La justicia es la virtud social por excelencia", "Aspecto pasivo: veracidad, empatía, amor", "Aspecto activo: laboriosidad, vida del hogar, ciudadanía"], "ejercicios_evaluables": [{"id": "m4-22", "label": "Cuestionario 9"}]}'::jsonb),
  ('m4-23', 'video', 'La justicia y los 4 temperamentos', 4, 8, true, 'activo', 'es', 31, '{"vimeoId": "924643798", "leccion": 10}'::jsonb),
  ('m4-25', 'test_profundo', 'Reto: Justicia', 4, 8, false, 'activo', 'es', 32, '{"caratula_titulo": "Reto: Justicia", "resumen_ficha": "¿Doy a cada uno lo que le corresponde?", "prioridad_ficha": 2, "descripcion": "Busca un momento tranquilo para realizar este ejercicio. Reflexiona con sinceridad sobre cada afirmación.\n\nNo hay respuestas correctas ni incorrectas: este autoexamen es una herramienta para tu crecimiento personal.", "preguntas": [{"texto": "Busco la excelencia en mi trabajo profesional.", "placeholder": "¿Pones tu mejor esfuerzo en tu trabajo?"}, {"texto": "Mi trabajo no es un medio de autoafirmación, sino un servicio a los otros.", "placeholder": "¿Trabajas para servir o para destacar?"}, {"texto": "No soy adicto al trabajo.", "placeholder": "¿Mantienes un equilibrio entre trabajo y vida personal?"}, {"texto": "Paso tiempo con la familia.", "placeholder": "¿Dedicas tiempo de calidad a tu familia?"}, {"texto": "Digo la verdad. Soy sincero y sencillo.", "placeholder": "¿Eres honesto en tus relaciones? ¿Evitas la doble cara?"}, {"texto": "Hago lo necesario para que la gente me conozca como realmente soy.", "placeholder": "¿Permites que los demás vean tu verdadero yo?"}, {"texto": "Defiendo la verdad moral, incluso si ello implica contradecir lo políticamente correcto.", "placeholder": "¿Tienes el valor de defender tus convicciones morales?"}, {"texto": "Perdono fácilmente y olvido rápidamente las ofensas.", "placeholder": "¿Guardas rencor o logras perdonar con facilidad?"}]}'::jsonb),
  ('m4-24', 'quiz', 'Cuestionario 10', 4, 8, false, 'activo', 'es', 33, '{"preguntas": [{"texto": "¿Qué puede aprender un colérico de la virtud de la justicia?", "opciones": ["Respetar a los demás (no pisarlos)", "Vencer la autoabsorción y dedicar tiempo a los demás", "Dominar la rutina de la vida profesional, familiar y social", "Vencer su pasividad"], "correcta": 0}, {"texto": "¿Qué puede aprender un melancólico de la virtud de la justicia?", "opciones": ["Respetar a los demás (no pisarlos)", "Vencer la autoabsorción y dedicar tiempo a los demás", "Dominar la rutina de la vida profesional, familiar y social", "Vencer su pasividad"], "correcta": 1}, {"texto": "¿Qué puede aprender un sanguíneo de la virtud de la justicia?", "opciones": ["Respetar a los demás (no pisarlos)", "Vencer la autoabsorción y dedicar tiempo a los demás", "Dominar la rutina de la vida profesional, familiar y social", "Vencer su pasividad"], "correcta": 2}, {"texto": "¿Qué puede aprender un flemático de la virtud de la justicia?", "opciones": ["Respetar a los demás (no pisarlos)", "Vencer la autoabsorción y dedicar tiempo a los demás", "Dominar la rutina de la vida profesional, familiar y social", "Vencer su pasividad"], "correcta": 3}]}'::jsonb),
  ('m4-concl-8', 'conclusion_modulo', 'Resumen: Justicia y temperamentos', 4, 8, false, 'activo', 'es', 34, '{"modulo_numero": 8, "modulo_titulo": "La justicia y los 4 temperamentos", "aprendizajes": ["Cómo cada temperamento afronta la justicia", "Reto personal: justicia en la vida profesional, familiar y social"], "ejercicios_evaluables": [{"id": "m4-24", "label": "Cuestionario 10"}, {"id": "m4-25", "label": "Reto: Justicia"}]}'::jsonb),
  ('m4-26', 'test_profundo', '12 principios básicos del Liderazgo Virtuoso', 4, 9, true, 'activo', 'es', 35, '{"caratula_titulo": "Revisión: 12 principios del Liderazgo Virtuoso", "leccion": 11, "descripcion": "Repasa los 12 principios fundamentales del liderazgo virtuoso. Lee cada pregunta y respuesta con atención: son el catecismo del líder virtuoso.", "titulo_lectura": "Los 12 principios básicos del Liderazgo Virtuoso", "lecturas": [[{"enfasis": "¿Por qué los líderes necesitan virtudes?"}, "El liderazgo auténtico debe basarse en una antropología auténtica, que incluya la aretología, la ciencia de la virtud.", "La virtud es un hábito de la mente, la voluntad y el corazón que nos permite alcanzar la excelencia y la eficacia personal. El liderazgo está intrínsecamente ligado a la virtud.", "En primer lugar, porque la virtud genera confianza, una condición esencial del liderazgo.", "En segundo lugar, el término «virtud», que procede del latín virtus que significa «fuerza» o «poder», es una energía dinámica que refuerza la capacidad de acción del líder.", "La virtud permite al líder hacer lo que la gente espera de él."], [{"enfasis": "¿Cuál es la esencia del liderazgo?"}, "La magnanimidad y la humildad, que son ante todo virtudes del corazón, son la esencia del liderazgo.", "La magnanimidad es el hábito de esforzarse por conseguir grandes cosas.", "Los líderes son magnánimos en sus sueños, sus visiones, su sentido de la misión; en su confianza, su audacia, su esperanza; en su esfuerzo; en el uso de medios para alcanzar sus metas; en los objetivos que se fijan para sí mismos y para los demás.", "La humildad es el hábito de vivir en el autoconocimiento. También es el hábito del servicio. Para un líder, practicar la humildad significa impulsar en lugar de presionar, inspirar en lugar de imponer, enseñar en lugar de recriminar.", "La magnanimidad y la humildad son las virtudes específicas del líder: juntas constituyen la esencia del liderazgo."], [{"enfasis": "¿Por qué el liderazgo es un ideal de vida?"}, "El liderazgo es un ideal de vida, porque las virtudes específicas a las que apela —la magnanimidad y la humildad— son en sí mismas ideales de vida.", "Magnanimidad y humildad son dos virtudes inseparables. Juntas constituyen un único ideal: el ideal de la dignidad y la grandeza humana.", "La magnanimidad es una afirmación de nuestra dignidad y grandeza personal; la humildad es una afirmación de la dignidad y grandeza de los demás.", "El liderazgo es un ideal de vida que reconoce, asimila y difunde la verdad sobre el hombre."], [{"enfasis": "¿Cuáles son los fundamentos del liderazgo?"}, "Las virtudes de la prudencia (sabiduría práctica), la fortaleza, el dominio de sí y la justicia, que son principalmente virtudes del intelecto y la voluntad, son los fundamentos del liderazgo.", "La prudencia mejora la capacidad del líder para tomar las decisiones correctas.", "La fortaleza le permite mantener el rumbo y resistir presiones de todo tipo.", "El dominio de sí subordina las emociones a la razón y proyecta su energía vital en el cumplimiento de la misión.", "La justicia les permite dar a cada uno lo que le corresponde.", "Puede que estas cuatro virtudes cardinales no sean la esencia del liderazgo, pero son los cimientos sin los cuales éste se derrumba."], [{"enfasis": "¿Qué es la humildad fundamental?"}, "La humildad fundamental es el hábito de vivir en la verdad.", "Vivir en la verdad es reconocer la propia condición de criatura (humildad metafísica), así como las debilidades naturales y los defectos personales (humildad espiritual).", "También significa reconocer nuestra dignidad y grandeza (humildad ontológica), así como nuestro talento y virtud (humildad psicológica). Esta humildad fundamental nos da el conocimiento de nosotros mismos.", "Si la humildad fraternal (el servicio) es la esencia y la cumbre del liderazgo, y la prudencia, la fortaleza, el dominio de sí y la justicia son sus cimientos, la humildad fundamental es su piedra angular."], [{"enfasis": "No se nace líder, se llega a serlo. ¿Por qué?"}, "La virtud es un hábito que se adquiere con la práctica.", "El liderazgo es una cuestión de carácter (virtud, libertad, crecimiento), no de temperamento (biología, condicionamiento, estancamiento).", "El temperamento puede favorecer el desarrollo de ciertas virtudes y frenar el de otras, pero llega un momento en la vida de un líder en que sus virtudes imprimen un carácter a su temperamento, de modo que éste deja de dominarle.", "El temperamento no es un obstáculo para el liderazgo: el obstáculo para el liderazgo es la falta de carácter, la ausencia de energía moral que nos hace esclavos de nuestra constitución biológica."], [{"enfasis": "¿Cuál es la diferencia entre Potestas y Auctoritas?"}, "El líder no gobierna mediante la potestas, poder implícito en sus funciones.", "Dirige mediante la auctoritas, la autoridad que proviene del carácter.", "Los que dirigen mediante la potestas, al carecer de autoridad, son líderes sólo de fachada.", "Es un círculo vicioso: los que carecen de autoridad (auctoritas) tienden a abusar de su poder (potestas), lo que provoca un mayor desgaste de su autoridad.", "El liderazgo no es una cuestión de rango o posición. El liderazgo es una forma de ser. Cualquiera, sea cual sea su lugar en la sociedad o en una organización, puede ser un líder."], [{"enfasis": "¿Qué papel desempeñan la razón, la voluntad y el corazón en la vida de un líder?"}, "Para crecer en la virtud, deben entrar en juego la razón, la voluntad y el corazón:", {"lista": ["Contemplar la virtud para percibir su belleza intrínseca y desearla ardientemente (papel del corazón).", "Discernir en cada situación la acción virtuosa que se debe emprender (papel de la razón).", "Actuar virtuosamente (papel de la voluntad)."]}], [{"enfasis": "Madurez de juicio, emociones y comportamiento"}, "Al practicar las virtudes, los líderes llegan a poseer la madurez en todos sus aspectos: en sus juicios, sus emociones y su comportamiento.", "Los signos de madurez son la confianza en uno mismo y la coherencia, la estabilidad psicológica, la alegría y el optimismo, la naturalidad, el sentido de la libertad, la responsabilidad y la paz interior.", "Los líderes no son escépticos ni cínicos, son realistas. El realismo es la capacidad de alimentar las nobles aspiraciones del alma, incluso cuando nos acosan nuestras propias debilidades personales. Ser realista es no ceder ante la debilidad, sino dominarla practicando las virtudes."], [{"enfasis": "El líder rechaza cualquier enfoque utilitarista de la virtud"}, "La virtud no es algo que cultive principalmente para ser eficaz en lo que hace.", "Cultiva la virtud ante todo para realizarse como ser humano.", "La eficacia no es el objetivo del crecimiento espiritual, es simplemente uno de sus muchos resultados."], [{"enfasis": "¿Cuál es la diferencia entre la ética de las virtudes y la ética de las reglas?"}, "Los líderes practican una ética de la virtud, en lugar de una ética basada en reglas.", "La ética de la virtud no niega la validez de las normas, pero afirma que éstas no son el fundamento último de la ética.", "Las reglas deben estar al servicio de la virtud. La ética de la virtud promueve ampliamente la creatividad del líder, mientras que la ética de las reglas acaba con ella."], [{"enfasis": "Virtudes humanas y virtudes cristianas"}, "La práctica de las virtudes específicamente cristianas de la fe, la esperanza y la caridad es una baza importante para el líder virtuoso.", "Estas virtudes sobrenaturales refuerzan las virtudes naturales de magnanimidad y humildad, que son la esencia del liderazgo, y las virtudes naturales de prudencia, fortaleza, dominio de sí y justicia, que son su fundamento.", "Ningún estudio del liderazgo que no tuviera en cuenta las virtudes sobrenaturales estaría completo."]], "preguntas": [{"texto": "Después de revisar los 12 principios, ¿cuál es el que más te interpela en este momento de tu vida? ¿Por qué?", "placeholder": "Ej: El principio de que «no se nace líder, se llega a serlo» me interpela porque..."}]}'::jsonb),
  ('m4-concl-9', 'conclusion_modulo', 'Resumen: 12 principios del LV', 4, 9, false, 'activo', 'es', 36, '{"modulo_numero": 9, "modulo_titulo": "12 principios básicos del Liderazgo Virtuoso", "aprendizajes": ["Los 12 principios básicos del liderazgo virtuoso", "Síntesis de las virtudes del liderazgo"], "ejercicios_evaluables": [{"id": "m4-26", "label": "12 principios"}]}'::jsonb),
  ('curso4-test-caracter', 'test_caracter', 'Test de carácter (comparativa)', 4, 0, true, 'activo', 'es', 37, '{}'::jsonb),
  ('m5-01', 'video', 'Corazón, intelecto y voluntad', 5, 0, true, 'activo', 'es', 1, '{"vimeoId": "924670798", "leccion": 1, "intro": [["Hay en el hombre tres ámbitos de libertad y responsabilidad, tres facultades espirituales:", {"chips": ["El corazón", "La razón", "La voluntad"]}, "Estas tres facultades no son independientes. Solo se pueden desarrollar de forma integrada."], ["Si una de ellas se aísla, **se corrompe y corrompe a todo el organismo humano**."], ["El racionalismo (el acento exclusivo en la razón), el voluntarismo (el acento exclusivo en la voluntad) y el sentimentalismo (el acento exclusivo en el corazón) son desequilibrios que paralizan al hombre y le hacen infeliz.", "En una persona equilibrada el corazón, la razón y la voluntad interactúan y cooperan armónicamente."]]}'::jsonb),
  ('m5-concl-0', 'conclusion_modulo', 'Resumen: Introducción', 5, 0, false, 'activo', 'es', 2, '{"modulo_numero": 0, "modulo_titulo": "Corazón, intelecto y voluntad", "aprendizajes": ["El corazón, la razón y la voluntad son las tres facultades espirituales del ser humano", "Si una de ellas se aísla, aparecen el racionalismo, el voluntarismo o el sentimentalismo", "Una persona equilibrada integra las tres"], "ejercicios_evaluables": []}'::jsonb),
  ('m5-02', 'video', 'Cuerpo, alma y espíritu', 5, 1, true, 'activo', 'es', 3, '{"vimeoId": "924671065", "leccion": 2}'::jsonb),
  ('m5-03', 'lectura', 'Cuerpo, alma y espíritu', 5, 1, false, 'activo', 'es', 4, '{"lecturas": [[{"enfasis": "Contempla este diagrama"}, {"imagen": "c5-cuerpo-alma-espiritu"}, "1. El corazón, la razón (intelecto, inteligencia) y la voluntad son facultades del espíritu humano.", "2. La razón y la voluntad son facultades exclusivamente espirituales.", "3. El corazón es a la vez una potencia espiritual y corporal. **Es el centro de la personalidad.** Es también el fundamento de la razón y de la voluntad."]]}'::jsonb),
  ('m5-04', 'quiz', 'Cuestionario 1', 5, 1, false, 'activo', 'es', 5, '{"preguntas": [{"texto": "El voluntarismo es…", "opciones": ["Cuando la razón absorbe el corazón y la voluntad", "Cuando la voluntad absorbe el corazón y la razón", "Cuando el corazón absorbe la razón y la voluntad", "Cuando la razón, el corazón y la voluntad están en armonía"], "correcta": 1}, {"texto": "El racionalismo es…", "opciones": ["Cuando la razón absorbe el corazón y la voluntad", "Cuando la voluntad absorbe el corazón y la razón", "Cuando el corazón absorbe la razón y la voluntad", "Cuando la razón, el corazón y la voluntad están en armonía"], "correcta": 0}, {"texto": "El sentimentalismo es…", "opciones": ["Cuando la razón absorbe el corazón y la voluntad", "Cuando la voluntad absorbe el corazón y la razón", "Cuando el corazón absorbe la razón y la voluntad", "Cuando la razón, el corazón y la voluntad están en armonía"], "correcta": 2}, {"texto": "¿Cuál es el centro de la personalidad humana?", "opciones": ["Su razón", "Su voluntad", "Su alma", "Su corazón"], "correcta": 3}]}'::jsonb),
  ('m5-concl-1', 'conclusion_modulo', 'Resumen: Cuerpo, alma y espíritu', 5, 1, false, 'activo', 'es', 6, '{"modulo_numero": 1, "modulo_titulo": "Cuerpo, alma y espíritu", "aprendizajes": ["El ser humano es cuerpo, alma y espíritu", "La razón y la voluntad son facultades exclusivamente espirituales", "El corazón está en los tres niveles: es el centro de la personalidad y el fundamento de la razón y de la voluntad"], "ejercicios_evaluables": [{"id": "m5-04", "label": "Cuestionario"}]}'::jsonb),
  ('m5-05', 'video', 'El triángulo blanco', 5, 2, true, 'activo', 'es', 7, '{"vimeoId": "924671113", "leccion": 3, "intro": [[{"enfasis": "Contempla este diagrama"}, {"imagen": "c5-triangulo-blanco"}, "El triángulo blanco es el lugar de encuentro de mis facultades espirituales. Mientras permanezco en el triángulo blanco, mis facultades espirituales interactúan entre ellas."], ["No tengo que estar necesariamente en el centro mismo del triángulo blanco.", "Puede ser que mi razón (si estoy cerca del ángulo superior izquierdo), mi voluntad (si estoy cerca del ángulo superior derecho) o mi corazón (si estoy cerca del ángulo inferior) desempeñe el papel más importante, pero esta prioridad no afecta a la armonía de mi ser.", {"enfasis": "La diversidad espiritual, como la biológica (los temperamentos), es algo excelente y necesario."}], ["Si salgo del triángulo blanco, **mi facultad dominante queda aislada y corrompida**: deja de interactuar con las otras dos facultades o, al menos, con una de ellas."]]}'::jsonb),
  ('m5-06', 'armonia_temperamento', 'Armonía espiritual y temperamento', 5, 2, false, 'activo', 'es', 8, '{"resumen_ficha": "Mi temperamento y mi facultad dominante", "prioridad_ficha": 1, "rueda": "c5-rueda-temperamentos", "texto_inicial": ["Existen cuatro temperamentos: colérico, melancólico, sanguíneo y flemático.", "Los temperamentos colérico y flemático son más bien racionales y voluntariosos; los temperamentos melancólico y sanguíneo son más bien intuitivos y receptivos."], "instruccion_rueda": "Pasa el ratón o toca cada temperamento.", "temperamentos": {"COL": {"nombre": "Colérico", "frase": "Si soy colérico de temperamento dominante, no debería sorprenderme descubrir que soy principalmente una criatura de voluntad.", "criatura": "Criatura de voluntad", "tendencia": "Voluntarismo"}, "MEL": {"nombre": "Melancólico", "frase": "Si soy melancólico, no debería sorprenderme descubrir que soy principalmente una criatura de corazón (profunda sensibilidad).", "criatura": "Criatura de corazón (profunda sensibilidad)", "tendencia": "Sentimentalismo"}, "SAN": {"nombre": "Sanguíneo", "frase": "Si soy sanguíneo, no debería sorprenderme descubrir que soy principalmente una criatura de corazón (emociones).", "criatura": "Criatura de corazón (emociones)", "tendencia": "Sentimentalismo"}, "FLE": {"nombre": "Flemático", "frase": "Si soy flemático, no debería sorprenderme descubrir que soy principalmente una criatura de razón.", "criatura": "Criatura de razón", "tendencia": "Racionalismo"}}, "cita_tendencia": "No es necesario, pero no sería sorprendente.", "texto_cultura": "El papel de la cultura y de la educación puede ser más fuerte que el de la biología. No me sorprendería descubrir, por ejemplo, que la voluntad ocupa el primer lugar en mi vida, aunque soy sanguíneo por temperamento; que el corazón prevalece, aunque soy flemático; que la mente domina, aunque soy melancólico.", "pregunta": "¿Cuál de las 3 facultades prevalece en mi vida?", "opciones": [{"valor": "razon", "texto": "La razón"}, {"valor": "voluntad", "texto": "La voluntad"}, {"valor": "corazon", "texto": "El corazón"}, {"valor": "iguales", "texto": "Las 3 trabajan por igual"}]}'::jsonb),
  ('m5-07', 'quiz', 'Cuestionario 2', 5, 2, false, 'activo', 'es', 9, '{"preguntas": [{"texto": "¿Qué enfermedad espiritual representa la mayor amenaza para los coléricos?", "opciones": ["El voluntarismo", "El sentimentalismo", "El racionalismo", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "¿Qué enfermedad espiritual representa la mayor amenaza para los flemáticos?", "opciones": ["El voluntarismo", "El sentimentalismo", "El racionalismo", "Todas las respuestas son correctas"], "correcta": 2}, {"texto": "¿Qué enfermedad espiritual representa la mayor amenaza para los sanguíneos y melancólicos?", "opciones": ["El voluntarismo", "El sentimentalismo", "El racionalismo", "Todas las respuestas son correctas"], "correcta": 1}, {"texto": "¿Hacia qué debe aspirar el ser humano en su vida?", "opciones": ["Desarrollar cualidades que coincidan con su temperamento", "Desarrollar cualidades opuestas a su temperamento", "Desarrollar las cualidades más valoradas por su entorno", "Aspirar a estar dentro del «Triángulo Blanco», que surge de la cooperación armoniosa entre la Razón, el Corazón y la Voluntad"], "correcta": 3}]}'::jsonb),
  ('m5-concl-2', 'conclusion_modulo', 'Resumen: El triángulo blanco', 5, 2, false, 'activo', 'es', 10, '{"modulo_numero": 2, "modulo_titulo": "El triángulo blanco", "aprendizajes": ["El triángulo blanco es el lugar de encuentro del corazón, la razón y la voluntad", "Puedes estar más cerca de una facultad, pero sin salir del triángulo", "Tu temperamento puede inclinarte hacia una facultad, pero la cultura y la educación pueden pesar más"], "ejercicios_evaluables": [{"id": "m5-07", "label": "Cuestionario"}]}'::jsonb),
  ('m5-08', 'video', 'El racionalista', 5, 3, true, 'activo', 'es', 11, '{"vimeoId": "924671239", "leccion": 4, "tendencia_temperamentos": ["FLE"]}'::jsonb),
  ('m5-09', 'lectura', 'El racionalista', 5, 3, false, 'activo', 'es', 12, '{"aviso_temperamento": {"FLE": "Tu temperamento es flemático. Havard dice que no sería sorprendente que un flemático, muy racional, tuviera cierta tendencia al racionalismo. No es necesario, pero presta atención a este módulo."}, "lecturas": [[{"imagen": "c5-R", "pie": "Immanuel Kant"}, "Al racionalista le interesa «el conocimiento del objeto, no el objeto del conocimiento»: quiere saber qué puede conocer del bien, de la verdad o de la belleza, pero no se deja tocar por ellos. Reduce toda la realidad a lo que su razón entiende; lo que no entiende, no existe. Para Havard es una falta de humildad: el orgullo de considerarse el centro de todas las verdades.", {"enfasis": "Síntoma"}, {"cita": "Nada me toca el corazón. Lo que me interesa es el conocimiento intelectual."}, {"enfasis": "Remedio"}, "**Déjate invadir, abrazar, transportar por lo que es más grande que tú.**"]]}'::jsonb),
  ('m5-10', 'quiz', 'Cuestionario 3', 5, 3, false, 'activo', 'es', 13, '{"preguntas": [{"texto": "¿El pensamiento de qué autor puede resumirse en esta frase: «Nada toca mi corazón. Solo me interesa el conocimiento intelectual»?", "opciones": ["Immanuel Kant", "Jean-Jacques Rousseau", "León Tolstói", "Blaise Pascal"], "correcta": 0}, {"texto": "¿Cuál es la característica de los racionalistas?", "opciones": ["Un conocimiento puramente intelectual de la realidad", "Una visión del mundo en la que «lo que mi razón no puede comprender, no existe»", "Una tendencia a considerarse el centro del mundo", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "¿A quién va dirigido este consejo: «Déjate asombrar por aquello que es más grande que tú»?", "opciones": ["Al racionalista", "Al voluntarista", "Al sentimentalista", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "¿Cuál es el principal pecado del racionalista?", "opciones": ["El orgullo", "La envidia", "La pereza", "La lujuria"], "correcta": 0}]}'::jsonb),
  ('m5-concl-3', 'conclusion_modulo', 'Resumen: El racionalista', 5, 3, false, 'activo', 'es', 14, '{"modulo_numero": 3, "modulo_titulo": "El racionalista", "aprendizajes": ["Al racionalista le interesa el conocimiento del objeto, no el objeto del conocimiento", "Reduce la realidad a lo que su razón entiende: es una forma de orgullo", "Remedio: déjate invadir, abrazar, transportar por lo que es más grande que tú"], "ejercicios_evaluables": [{"id": "m5-10", "label": "Cuestionario"}]}'::jsonb),
  ('m5-11', 'video', 'Los voluntaristas', 5, 4, true, 'activo', 'es', 15, '{"vimeoId": "924671495", "leccion": 5, "tendencia_temperamentos": ["COL"]}'::jsonb),
  ('m5-12', 'lectura', 'Los voluntaristas', 5, 4, false, 'activo', 'es', 16, '{"aviso_temperamento": {"COL": "Tu temperamento es colérico. Havard dice que no sería sorprendente que un colérico, gente de la acción, tuviera cierta tendencia al voluntarismo. No es necesario, pero presta atención a este módulo."}, "lecturas": [[{"imagen": "c5-VR", "pie": "St. John Rivers, en «Jane Eyre», de Charlotte Brontë"}, "Está convencido de que el corazón es malo y de que ir contra él le hace mejor: todo el mérito está en la voluntad. Rivers quiere casarse con Jane sin amarla, porque sería una buena esposa de misionero. Para Havard, a veces hay que dejar el corazón de lado, pero no toda una vida: una voluntad que va siempre contra el corazón es una voluntad infeliz.", {"enfasis": "Síntoma"}, {"cita": "Silencio mi corazón para aumentar el valor de mi voluntad."}, {"enfasis": "Remedio"}, "**Aprende a escuchar tu corazón.**"], [{"imagen": "c5-VM", "pie": "Clint Eastwood"}, "Tiene miedo de sus sentimientos: los esconde y ve la sensibilidad de los demás como debilidad. Confunde sensibilidad con sensiblería. Havard señala que muchos son coléricos, pero que no es sencillamente un problema de temperamento: tiene mucho que ver con la cultura en la que uno se ha educado. Para él, la sensibilidad es una parte muy importante de la excelencia humana.", {"enfasis": "Síntoma"}, {"cita": "Experimento vergüenza de tener sentimientos."}, {"enfasis": "Remedio"}, "**Deja de confundir la sensibilidad con el sentimentalismo.**"], [{"imagen": "c5-VI", "pie": "«El obrero y la koljosiana», estatua soviética para la Exposición Universal de París"}, "Es pura voluntad que no acepta la razón ni la naturaleza humana: «me reinvento cada día». Havard lo relaciona con Nietzsche. La ideología le lleva a destrozar su inteligencia y su corazón, y le hace infeliz.", {"enfasis": "Síntoma"}, {"cita": "¡Viva la voluntad! ¡Abajo la razón! ¡Viva la humanidad progresista! ¡Abajo la naturaleza humana!"}, {"enfasis": "Remedio"}, "**Renuncia a la ideología. Respeta los principios inmutables de la naturaleza humana.**"], [{"imagen": "c5-VC", "pie": "El fariseo"}, "Vive de lo correcto y lo incorrecto: lo política, religiosa o culturalmente correcto. Para él las reglas son un fin en sí mismas, cuando deberían estar al servicio de la virtud. No reflexiona, y juzga a quien no las cumple. Para Havard, las personas son más importantes que las reglas.", {"enfasis": "Síntoma"}, {"cita": "El cumplimiento de reglas y rituales es la norma suprema de moralidad."}, {"enfasis": "Remedio"}, "**Aprende a querer a los hombres más que a lo religiosa, cultural o socialmente correcto.**"]]}'::jsonb),
  ('m5-13', 'quiz', 'Cuestionario 4', 5, 4, false, 'activo', 'es', 17, '{"preguntas": [{"texto": "¿Qué tipo de voluntarista corresponde a esta cita: «Cuanto más silencio impongo a mi corazón, más me acerco a la perfección moral»?", "opciones": ["El voluntarista religioso", "El voluntarista machista", "El voluntarista ideológico", "El voluntarista conformista"], "correcta": 0}, {"texto": "¿Qué tipo de voluntarista corresponde a esta cita: «Me avergüenzo de mis emociones»?", "opciones": ["El voluntarista religioso", "El voluntarista machista", "El voluntarista ideológico", "El voluntarista conformista"], "correcta": 1}, {"texto": "¿Qué tipo de voluntarista corresponde a esta cita: «¡Viva la humanidad progresista! ¡Abajo las cadenas de la naturaleza humana!»?", "opciones": ["El voluntarista religioso", "El voluntarista machista", "El voluntarista ideológico", "El voluntarista conformista"], "correcta": 2}, {"texto": "¿Qué tipo de voluntarista corresponde a esta cita: «La observancia de reglas y ritos es la norma suprema de la moralidad»?", "opciones": ["El voluntarista religioso", "El voluntarista machista", "El voluntarista ideológico", "El voluntarista conformista"], "correcta": 3}]}'::jsonb),
  ('m5-concl-4', 'conclusion_modulo', 'Resumen: Los voluntaristas', 5, 4, false, 'activo', 'es', 18, '{"modulo_numero": 4, "modulo_titulo": "Los voluntaristas", "aprendizajes": ["En el voluntarista, la voluntad absorbe el corazón y la razón", "Hay cuatro tipos: religioso, machista, ideológico y conformista", "Cada uno tiene su remedio: escuchar el corazón, aceptar la sensibilidad, respetar la naturaleza humana, querer a las personas más que a las reglas"], "ejercicios_evaluables": [{"id": "m5-13", "label": "Cuestionario"}]}'::jsonb),
  ('m5-14', 'video', 'Los sentimentalistas', 5, 5, true, 'activo', 'es', 19, '{"vimeoId": "924672224", "leccion": 6, "tendencia_temperamentos": ["MEL", "SAN"]}'::jsonb),
  ('m5-15', 'lectura', 'Los sentimentalistas', 5, 5, false, 'activo', 'es', 20, '{"aviso_temperamento": {"MEL": "Tu temperamento es melancólico. Havard dice que no sería sorprendente que un melancólico, gente del corazón (corazón interior), tuviera cierta tendencia al sentimentalismo. No es necesario, pero presta atención a este módulo.", "SAN": "Tu temperamento es sanguíneo. Havard dice que no sería sorprendente que un sanguíneo, gente del corazón (corazón exterior), tuviera cierta tendencia al sentimentalismo. No es necesario, pero presta atención a este módulo."}, "lecturas": [[{"imagen": "c5-SV", "pie": "«Desconocida», de Iván Kramskói, que muchos asocian con Ana Karénina"}, "Hace el bien por lo bien que le hace sentir: no busca el bien por sí mismo, sino el placer o la paz que le da. Havard propone una prueba: si hacer el bien deja de darte satisfacción y sigues haciéndolo, es que buscabas el bien por el bien.", {"enfasis": "Síntoma"}, {"cita": "Amo el bien por el placer que me da."}, {"enfasis": "Remedio"}, "**Aprende a amar el bien por sí mismo.**"], [{"imagen": "c5-SI", "pie": "Jean-Jacques Rousseau"}, "Confunde la conciencia con el corazón: lo que siente es, para él, siempre bueno. Rousseau entregó a sus hijos al Estado convencido de que hacía bien, porque su corazón se lo decía. Para Havard, la conciencia es la voz de Dios en nosotros y está por encima del corazón.", {"enfasis": "Síntoma"}, {"cita": "La verdad es lo que siente mi corazón."}, {"enfasis": "Remedio"}, "**Escucha tu conciencia antes de escuchar tu corazón.**"], [{"imagen": "c5-SC", "pie": "Rudin, personaje de Iván Turguénev"}, "Sabe lo que tiene que hacer, pero renuncia en cuanto aparece un conflicto. Rudin, enamorado de Natalia, se echa atrás al saber que la madre de ella se opone. Havard lo contrapone a Juana de Arco, que siguió su misión aunque sus padres sufrieran.", {"enfasis": "Síntoma"}, {"cita": "Renuncio a lo bueno tan pronto como se convierte en una fuente de conflictos."}, {"enfasis": "Remedio"}, "**Aprende a gestionar las contradicciones con sinceridad y firmeza.**"]]}'::jsonb),
  ('m5-17', 'test_corazon', 'Test del corazón', 5, 5, false, 'activo', 'es', 21, '{"descripcion": "Evalúa la libertad de tu corazón. 32 preguntas sobre las ocho enfermedades espirituales que acabas de conocer."}'::jsonb),
  ('m5-18', 'objetivos_corazon', 'Mis objetivos prácticos', 5, 5, false, 'activo', 'es', 22, '{"resumen_ficha": "Mis objetivos prácticos", "prioridad_ficha": 2, "paso_test": "m5-17", "cuantas": 2, "texto_intro": "Según tu Test del corazón, estas son las dos enfermedades en las que más puntúas. Para cada una, escribe tus objetivos prácticos: qué vas a hacer, en concreto, para aplicar el remedio.", "placeholder": "Escribe uno o varios objetivos concretos…", "fichas": {"R": {"nombre": "El racionalista", "nombre_test": "Racionalismo", "imagen": "c5-R", "pie": "Immanuel Kant", "havard": "Al racionalista le interesa «el conocimiento del objeto, no el objeto del conocimiento»: quiere saber qué puede conocer del bien, de la verdad o de la belleza, pero no se deja tocar por ellos. Reduce toda la realidad a lo que su razón entiende; lo que no entiende, no existe. Para Havard es una falta de humildad: el orgullo de considerarse el centro de todas las verdades.", "sintoma": "Nada me toca el corazón. Lo que me interesa es el conocimiento intelectual.", "remedio": "Déjate invadir, abrazar, transportar por lo que es más grande que tú."}, "VR": {"nombre": "El voluntarista religioso", "nombre_test": "Voluntarismo religioso", "imagen": "c5-VR", "pie": "St. John Rivers, en «Jane Eyre», de Charlotte Brontë", "havard": "Está convencido de que el corazón es malo y de que ir contra él le hace mejor: todo el mérito está en la voluntad. Rivers quiere casarse con Jane sin amarla, porque sería una buena esposa de misionero. Para Havard, a veces hay que dejar el corazón de lado, pero no toda una vida: una voluntad que va siempre contra el corazón es una voluntad infeliz.", "sintoma": "Silencio mi corazón para aumentar el valor de mi voluntad.", "remedio": "Aprende a escuchar tu corazón."}, "VM": {"nombre": "El voluntarista machista", "nombre_test": "Voluntarismo machista", "imagen": "c5-VM", "pie": "Clint Eastwood", "havard": "Tiene miedo de sus sentimientos: los esconde y ve la sensibilidad de los demás como debilidad. Confunde sensibilidad con sensiblería. Havard señala que muchos son coléricos, pero que no es sencillamente un problema de temperamento: tiene mucho que ver con la cultura en la que uno se ha educado. Para él, la sensibilidad es una parte muy importante de la excelencia humana.", "sintoma": "Experimento vergüenza de tener sentimientos.", "remedio": "Deja de confundir la sensibilidad con el sentimentalismo."}, "VI": {"nombre": "El voluntarista ideológico", "nombre_test": "Voluntarismo ideológico", "imagen": "c5-VI", "pie": "«El obrero y la koljosiana», estatua soviética para la Exposición Universal de París", "havard": "Es pura voluntad que no acepta la razón ni la naturaleza humana: «me reinvento cada día». Havard lo relaciona con Nietzsche. La ideología le lleva a destrozar su inteligencia y su corazón, y le hace infeliz.", "sintoma": "¡Viva la voluntad! ¡Abajo la razón! ¡Viva la humanidad progresista! ¡Abajo la naturaleza humana!", "remedio": "Renuncia a la ideología. Respeta los principios inmutables de la naturaleza humana."}, "VC": {"nombre": "El voluntarista conformista", "nombre_test": "Voluntarismo conformista", "imagen": "c5-VC", "pie": "El fariseo", "havard": "Vive de lo correcto y lo incorrecto: lo política, religiosa o culturalmente correcto. Para él las reglas son un fin en sí mismas, cuando deberían estar al servicio de la virtud. No reflexiona, y juzga a quien no las cumple. Para Havard, las personas son más importantes que las reglas.", "sintoma": "El cumplimiento de reglas y rituales es la norma suprema de moralidad.", "remedio": "Aprende a querer a los hombres más que a lo religiosa, cultural o socialmente correcto."}, "SV": {"nombre": "El sentimentalista voluptuoso", "nombre_test": "Sentimentalismo voluptuoso", "imagen": "c5-SV", "pie": "«Desconocida», de Iván Kramskói, que muchos asocian con Ana Karénina", "havard": "Hace el bien por lo bien que le hace sentir: no busca el bien por sí mismo, sino el placer o la paz que le da. Havard propone una prueba: si hacer el bien deja de darte satisfacción y sigues haciéndolo, es que buscabas el bien por el bien.", "sintoma": "Amo el bien por el placer que me da.", "remedio": "Aprende a amar el bien por sí mismo."}, "SI": {"nombre": "El sentimentalista demente", "nombre_test": "Sentimentalismo demente", "imagen": "c5-SI", "pie": "Jean-Jacques Rousseau", "havard": "Confunde la conciencia con el corazón: lo que siente es, para él, siempre bueno. Rousseau entregó a sus hijos al Estado convencido de que hacía bien, porque su corazón se lo decía. Para Havard, la conciencia es la voz de Dios en nosotros y está por encima del corazón.", "sintoma": "La verdad es lo que siente mi corazón.", "remedio": "Escucha tu conciencia antes de escuchar tu corazón."}, "SC": {"nombre": "El sentimentalista cobarde", "nombre_test": "Sentimentalismo cobarde", "imagen": "c5-SC", "pie": "Rudin, personaje de Iván Turguénev", "havard": "Sabe lo que tiene que hacer, pero renuncia en cuanto aparece un conflicto. Rudin, enamorado de Natalia, se echa atrás al saber que la madre de ella se opone. Havard lo contrapone a Juana de Arco, que siguió su misión aunque sus padres sufrieran.", "sintoma": "Renuncio a lo bueno tan pronto como se convierte en una fuente de conflictos.", "remedio": "Aprende a gestionar las contradicciones con sinceridad y firmeza."}}}'::jsonb),
  ('m5-16', 'quiz', 'Cuestionario 5', 5, 5, false, 'activo', 'es', 23, '{"preguntas": [{"texto": "¿Qué tipo de sentimentalista corresponde a esta cita: «Hago el bien por el placer que me proporciona»?", "opciones": ["El sentimentalista voluptuoso", "El sentimentalista demente", "El sentimentalista cobarde", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "¿Qué tipo de sentimentalista corresponde a esta cita: «La verdad es lo que siente mi corazón»?", "opciones": ["El sentimentalista voluptuoso", "El sentimentalista demente", "El sentimentalista cobarde", "Todas las respuestas son correctas"], "correcta": 1}, {"texto": "¿Qué tipo de sentimentalista corresponde a esta cita: «Renuncio al bien cuando se convierte en una fuente de conflicto»?", "opciones": ["El sentimentalista voluptuoso", "El sentimentalista demente", "El sentimentalista cobarde", "Todas las respuestas son correctas"], "correcta": 2}, {"texto": "¿Qué consejo se le puede dar a un sentimentalista voluptuoso?", "opciones": ["Escucha tu conciencia antes de escuchar tu corazón", "Aprende a amar el bien por sí mismo", "Aprende a afrontar los conflictos de manera abierta y valiente", "Deja de creer que sensibilidad y sentimentalismo son lo mismo"], "correcta": 1}]}'::jsonb),
  ('m5-19', 'lectura', 'Lecturas recomendadas', 5, 5, false, 'activo', 'es', 24, '{"lecturas": [["Havard cierra el curso recomendando dos libros:", {"enfasis": "«Corazones libres»"}, "Retoma todos los temas del curso con mucho más detalle.", {"enfasis": "«Siete profetas»"}, "Habla de tres pensadores que, para Havard, separaron las facultades (Descartes, Nietzsche y Rousseau) y de cuatro que las vivieron unidas (Pascal, Kierkegaard, Dostoievski y Soloviov)."]]}'::jsonb),
  ('m5-concl-5', 'conclusion_modulo', 'Resumen: Los sentimentalistas', 5, 5, false, 'activo', 'es', 25, '{"modulo_numero": 5, "modulo_titulo": "Los sentimentalistas", "aprendizajes": ["En el sentimentalista, el corazón absorbe la razón y la voluntad", "Hay tres tipos: voluptuoso, demente y cobarde", "Con el Test del corazón has identificado tus tendencias y fijado tus objetivos prácticos"], "ejercicios_evaluables": [{"id": "m5-16", "label": "Cuestionario"}]}'::jsonb),
  ('curso5-test-corazon', 'test_corazon', 'Test del corazón', 5, 0, true, 'activo', 'es', 26, '{}'::jsonb),
  ('m6-01', 'video', 'Descubre tu misión', 6, 0, true, 'activo', 'es', 1, '{"vimeoId": "924678340", "leccion": 1, "intro": [["Mi misión es mi contribución específica al bien común de la humanidad.", "No está determinada en el tiempo: **es algo que hago sin interrupción**."], ["Mi misión…", {"chips": ["Orienta mi existencia", "Determina mis objetivos", "Me mantiene centrado"]}], ["Para descubrir mi misión, tengo que responder a dos preguntas:"], [{"caja": "¿Cuál es mi historia y cuál es mi talento?"}], [{"caja": "¿Cuál es el reto cultural o social al que me siento llamado a responder con pasión y determinación?"}]]}'::jsonb),
  ('m6-02', 'video', '¿Qué es una misión?', 6, 0, false, 'activo', 'es', 2, '{"vimeoId": "924678464", "leccion": 2, "continua_modulo": true}'::jsonb),
  ('m6-03', 'lectura', '¿Qué es una misión?', 6, 0, false, 'activo', 'es', 3, '{"lecturas": [[{"enfasis": "Vocación: una llamada a ser"}, "Viene del latín «vocare», llamar. Estoy llamado a ser una persona concreta. **La vocación es el marco de mi vida.** Para Havard, descubrirla supone un mínimo de sentido religioso."], [{"enfasis": "Misión: una llamada a la acción"}, "Viene del latín «missio», enviar. Estoy enviado a hacer algo concreto. **La misión es mi contribución al bien común de la humanidad.**", "Hacen falta las dos: una vocación sin misión no tiene contenido; una misión sin vocación no tiene marco."], ["Mi misión es **específica**. «Ser una buena madre» o «ser el número uno» no son misiones: son demasiado genéricas.", "Tengo **una sola misión** y la cumplo todo el tiempo, de mil maneras distintas, hasta el final de mi vida. No es como el soldado, que recibe una misión tras otra.", {"cita": "Tú eres tu misión."}]]}'::jsonb),
  ('m6-04', 'quiz', 'Cuestionario 1', 6, 0, false, 'activo', 'es', 4, '{"preguntas": [{"texto": "¿Qué es una Misión?", "opciones": ["Una respuesta activa a un desafío de carácter cultural o social", "Tu contribución específica al bien común de la humanidad", "Una definición de lo que te hace único", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "¿En qué se diferencia la Misión de la Vocación?", "opciones": ["La vocación es una forma de ser, la Misión es lo que debo hacer", "La vocación nace en el hombre como una iniciativa desde lo alto (de Dios, según cómo lo entienda), mientras que la Misión es formulada por la propia persona como el fruto de la puesta en práctica de sus talentos", "La vocación es un marco de vida para la persona y para su Misión", "Todas las respuestas son correctas"], "correcta": 3}, {"texto": "Completa la frase: «Yo soy…»", "opciones": ["Mi Misión", "Mis deseos", "Mis pensamientos", "Todas las respuestas son correctas"], "correcta": 0}, {"texto": "¿Cuánto tiempo se necesita para cumplir una Misión?", "opciones": ["1 año", "5 años", "10 años", "Toda la vida"], "correcta": 3}]}'::jsonb),
  ('m6-concl-1', 'conclusion_modulo', 'Resumen: ¿Qué es una misión?', 6, 0, false, 'activo', 'es', 5, '{"modulo_numero": 0, "modulo_titulo": "¿Qué es una misión?", "aprendizajes": ["Mi misión es mi contribución específica al bien común de la humanidad", "La vocación es una llamada a ser; la misión, una llamada a la acción", "Tengo una sola misión y la cumplo toda la vida: yo soy mi misión"], "ejercicios_evaluables": [{"id": "m6-04", "label": "Cuestionario"}]}'::jsonb),
  ('m6-05', 'video', 'Ejemplos de misiones', 6, 1, false, 'activo', 'es', 6, '{"vimeoId": "924678683", "leccion": 3}'::jsonb),
  ('m6-06', 'lectura', 'Ejemplos de misiones', 6, 1, false, 'activo', 'es', 7, '{"lecturas": [["Havard pone cuatro ejemplos. En todos, la misión nace al unir dos cosas:", {"chips": ["Mi talento", "El desafío del mundo en que vivo"]}], [{"enfasis": "Aleksandr Solzhenitsyn"}, "Escritor ruso, Premio Nobel de Literatura (1918–2008).", {"enfasis": "Misión"}, {"cita": "Quería ser la memoria de un pueblo víctima de una tragedia indecible."}, {"enfasis": "Talento"}, "Escribir. En el gulag, sin papel, escribía de memoria, y sus compañeros de cárcel le decían que lo hacía muy bien.", {"enfasis": "Desafío"}, "Los millones de personas sin voz que morían bajo el comunismo, y la grandeza de quienes lo afrontaron con dignidad."], [{"enfasis": "Jérôme Lejeune"}, "Médico y genetista francés (1926–1994).", {"enfasis": "Misión"}, {"cita": "Quería defender la verdad científica y la gran verdad moral que se deriva de ella."}, {"enfasis": "Talento"}, "La ciencia. Fue un genetista de altísimo nivel: descubrió la causa del síndrome de Down.", {"enfasis": "Desafío"}, "Defender la vida humana con la verdad científica."], [{"enfasis": "Madre Teresa de Calcuta"}, "Fundadora de las Misioneras de la Caridad (1910–1997).", {"enfasis": "Misión"}, {"cita": "Quería ser madre de los más pobres entre los pobres de la tierra."}, {"enfasis": "Talento"}, "La maternidad espiritual.", {"enfasis": "Desafío"}, "La pobreza extrema: que quienes habían vivido como animales murieran como ángeles, conociendo el amor.", "Un día le ofrecieron millones de dólares para dirigir grandes hospitales. Ella respondió:", {"cita": "Mi misión es ser una madre, no una enfermera."}, "**Una misión clara ayuda a tomar buenas decisiones.**"], [{"enfasis": "Alexandre Havard"}, "Fundador del Liderazgo Virtuoso.", {"enfasis": "Misión"}, {"cita": "Encender los corazones para la grandeza."}, {"enfasis": "Talento"}, "Enseñar e inspirar: ir al corazón de las personas, y no solo a su inteligencia.", {"enfasis": "Desafío"}, "La pusilanimidad: un mundo que hace a las personas pequeñas."]]}'::jsonb),
  ('m6-07', 'quiz', 'Cuestionario 2', 6, 1, false, 'activo', 'es', 8, '{"preguntas": [{"texto": "¿A quién pertenece esta misión? «Ser la memoria de un pueblo víctima de una gran tragedia.»", "opciones": ["Aleksandr Solzhenitsyn", "Jérôme Lejeune", "Madre Teresa", "Alexandre Havard"], "correcta": 0}, {"texto": "¿A quién pertenece esta misión? «Afirmar la verdad científica y la verdad moral que de ella se deriva.»", "opciones": ["Aleksandr Solzhenitsyn", "Jérôme Lejeune", "Madre Teresa", "Alexandre Havard"], "correcta": 1}, {"texto": "¿A quién pertenece esta misión? «Ser una madre para los más pobres entre los pobres de la tierra.»", "opciones": ["Aleksandr Solzhenitsyn", "Jérôme Lejeune", "Madre Teresa", "Alexandre Havard"], "correcta": 2}, {"texto": "¿A quién pertenece esta misión? «Encender los corazones para la grandeza.»", "opciones": ["Aleksandr Solzhenitsyn", "Jérôme Lejeune", "Madre Teresa", "Alexandre Havard"], "correcta": 3}]}'::jsonb),
  ('m6-concl-2', 'conclusion_modulo', 'Resumen: Ejemplos de misiones', 6, 1, false, 'activo', 'es', 9, '{"modulo_numero": 1, "modulo_titulo": "Ejemplos de misiones", "aprendizajes": ["Una misión nace al unir mi talento y el desafío del mundo en que vivo", "Cuatro misiones: ser memoria, defender la verdad científica, ser madre, encender los corazones", "Una misión clara ayuda a tomar buenas decisiones"], "ejercicios_evaluables": [{"id": "m6-07", "label": "Cuestionario"}]}'::jsonb),
  ('m6-08', 'video', '¿Por qué una misión?', 6, 2, false, 'activo', 'es', 10, '{"vimeoId": "924679235", "leccion": 4}'::jsonb),
  ('m6-09', 'lectura', '¿Por qué una misión?', 6, 2, false, 'activo', 'es', 11, '{"lecturas": [["Havard da tres razones para tener una misión:", {"enfasis": "Orienta mi existencia"}, "Me da una dirección. Lejeune sabía que lo suyo era hablar como científico, no como filósofo ni como teólogo."], [{"enfasis": "Determina mis objetivos"}, "La misión fija los objetivos, y no al revés. Sin misión, los objetivos se contradicen unos a otros porque nada los unifica: se hacen muchas cosas y al final no se hace nada."], [{"enfasis": "Me mantiene centrado"}, "Un visitante hablaba con Solzhenitsyn, que le escuchaba con cortesía. En cuanto dijo que había estado en un campo de concentración, Solzhenitsyn sacó papel y lápiz y se lo preguntó todo. Era la memoria de esa época."]]}'::jsonb),
  ('m6-10', 'quiz', 'Cuestionario 3', 6, 2, false, 'activo', 'es', 12, '{"preguntas": [{"texto": "¿Cuál de las siguientes afirmaciones es incorrecta?", "opciones": ["Mi misión define mis objetivos", "Mi misión me permite estar enfocado", "Mis objetivos definen mi misión", "Mi misión da dirección a mi existencia"], "correcta": 2}, {"texto": "A la Madre Teresa le ofrecieron millones para dirigir grandes hospitales. ¿Por qué dijo que no?", "opciones": ["No quería depender del dinero", "Su misión era ser madre de los más pobres, no enfermera", "No sabía de medicina", "Prefería trabajar sola"], "correcta": 1}, {"texto": "¿Qué le pasa a quien se fija objetivos sin tener una misión?", "opciones": ["Sus objetivos se contradicen, porque nada los unifica", "Los cumple antes", "Se fija objetivos más ambiciosos", "No le pasa nada"], "correcta": 0}, {"texto": "Solzhenitsyn sacaba papel y lápiz en cuanto alguien le hablaba de un campo de concentración. ¿Qué muestra este ejemplo?", "opciones": ["Que una misión te mantiene centrado", "Que era periodista", "Que desconfiaba de la gente", "Que buscaba ideas para una novela"], "correcta": 0}]}'::jsonb),
  ('m6-concl-3', 'conclusion_modulo', 'Resumen: ¿Por qué una misión?', 6, 2, false, 'activo', 'es', 13, '{"modulo_numero": 2, "modulo_titulo": "¿Por qué una misión?", "aprendizajes": ["Mi misión orienta mi existencia: me da una dirección", "Mi misión determina mis objetivos, y no al revés", "Mi misión me mantiene centrado en lo esencial"], "ejercicios_evaluables": [{"id": "m6-10", "label": "Cuestionario"}]}'::jsonb),
  ('m6-11', 'video', 'Mi misión', 6, 3, false, 'activo', 'es', 14, '{"vimeoId": "924679399", "leccion": 5}'::jsonb),
  ('m6-concl-4', 'conclusion_modulo', 'Resumen: Mi misión', 6, 3, false, 'activo', 'es', 15, '{"modulo_numero": 3, "modulo_titulo": "Mi misión", "aprendizajes": ["La misión es fruto del autoconocimiento; si no, es un capricho", "Para descubrirla, cuento mi historia, reconozco mis talentos y miro el desafío de mi tiempo", "Mi misión debe ser corta, para recordarla, y densa, para cumplirla cada día"], "ejercicios_evaluables": []}'::jsonb),
  ('m6-proyecto', 'proyecto_mision', 'Plan para descubrir tu misión', 6, 0, false, 'activo', 'es', 16, '{"proyecto_final": true, "resumen_ficha": true, "prioridad_ficha": 1, "recuerdo_curso2": {"paso": "m2-14", "indices": [7, 8, 9], "titulo": "Lo que escribiste en el Curso 2", "texto": "En el Curso 2 reflexionaste sobre tu misión. Esto es lo que escribiste:"}, "secciones": [{"id": "historia", "titulo": "Mi historia", "lecturas": [["Para responder a la pregunta «¿Quién soy?» necesito conocer bien mi historia y contemplarla.", "**Es mi historia, y no mis caprichos, la que define mi misión.**", {"cita": "Mi historia no es sólo mi historia. Es también la historia de las personas que viven en mí de un modo u otro porque su influencia sobre mí fue considerable."}], ["Recordar es un esfuerzo moral: me esfuerzo por recordar lo bueno que he recibido y por ser agradecido. Si hay heridas, la única manera de curarlas es perdonar.", "El género de mi relato es el de la **autobiografía espiritual**. Escribo para conocerme y comprenderme, no para que otros me lean. Escribo en círculo, como vuela el águila: vuelvo una y otra vez a mis raíces."]], "preguntas": [{"texto": "Las personas que han dejado en mí una huella profunda, un rastro indeleble.", "placeholder": "¿Quiénes son? ¿Qué te dejó cada una de ellas?", "obligatoria": true, "ejemplo": "Havard dedica los tres primeros capítulos de su biografía espiritual a sus abuelos, sus padres y sus hermanos. Sus abuelos habían sufrido la Primera Guerra Mundial y habían huido del bolchevismo; de cada uno recibió algo distinto, y en todos vio grandeza. Estas personas siguen viviendo en ti, aunque hayan muerto."}, {"texto": "Los acontecimientos que forjaron mi personalidad.", "placeholder": "¿Qué momentos te marcaron? ¿Qué descubriste en ellos?", "obligatoria": false, "ejemplo": "Al llegar a la universidad, en los años 70, Havard vio que el mundo que le rodeaba no se parecía a la grandeza que había conocido en su familia: era un mundo de consumismo y de gente sin raíces. Ese contraste le marcó."}, {"texto": "Mi país, sus grandezas y sus miserias.", "placeholder": "¿Qué hay de excepcional en tu país y en su tradición? ¿Qué te hace sufrir de él hoy?", "obligatoria": false, "ejemplo": "Para Havard, cada país tiene unos dones propios y una misión en la historia. Eres miembro de esa familia nacional y has recibido mucho de ella: descubre su grandeza. Pero sé objetivo y habla también de lo que va contra lo mejor de tu patria."}, {"texto": "Libros, películas y música que me inspiran.", "placeholder": "¿Qué obras te han tocado? ¿Qué dicen de ti?", "obligatoria": false, "ejemplo": "Andréi Tarkovski estrenó «El espejo» en los años 70. Un día recibió la carta de una mujer que le preguntaba cómo conocía su vida: no la conocía, pero la película contaba la esencia de su vida. Si una obra te toca, es porque habla de ti."}, {"texto": "Intento descubrir el tema principal de mi existencia.", "placeholder": "¿Qué vuelve una y otra vez en tu historia?", "obligatoria": true, "ejemplo": "Así descubrió Havard el suyo: «Vi grandeza en mis padres, mis abuelos, mis amigos, mis profesores. Al mismo tiempo, vi un océano de pusilanimidad, producto del consumismo y del relativismo moral, que barría el mundo. Observé con asombro la aparición de nuevas criaturas, las del Mundo feliz de Aldous Huxley: seres sin pasado, sin patria, sin familia, sin Dios. Vi a los hombres sin pecho de C.S. Lewis, a los amputados de corazón de Jacques Brel. Me aterroricé y decidí actuar. Mi misión —encender corazones para la grandeza— se convirtió en mi respuesta personal a esta catástrofe antropológica.» (Alexandre Havard, «Mi camino hacia el liderazgo virtuoso»)"}]}, {"id": "talentos", "titulo": "Mis talentos", "lecturas": [["Tu misión está relacionada con tu historia y con tus talentos. Pregúntate: **¿Qué se me da bien?**", "Hablar de tus talentos no es orgullo: es humildad, vivir en la verdad sobre ti mismo. Tus talentos son un don; tú solo los multiplicas. Si no los conoces bien, pide a otros su opinión.", "**Mi misión está donde está mi excelencia.**"]], "preguntas": [{"texto": "Temperamento", "placeholder": "¿Qué talentos te da tu temperamento?", "obligatoria": false, "ayuda_temperamento": true, "ejemplo": "Havard es melancólico: su temperamento le orienta hacia las ideas y la creatividad, y eso le ayuda a avanzar en su misión de encender los corazones para la grandeza."}, {"texto": "Carácter", "placeholder": "¿Qué virtudes ya tienes desarrolladas?", "obligatoria": false}, {"texto": "Cuerpo", "placeholder": "¿Qué dones físicos tienes?", "obligatoria": false}, {"texto": "Corazón", "placeholder": "¿Qué te mueve? ¿Qué sabes amar?", "obligatoria": false}, {"texto": "Voluntad", "placeholder": "¿En qué eres constante y firme?", "obligatoria": false}, {"texto": "Inteligencia", "placeholder": "¿Qué entiendes con facilidad?", "obligatoria": false}, {"texto": "Talento específico", "placeholder": "¿Qué haces de forma excelente?", "obligatoria": true, "ejemplo": "Havard daba clase en la Universidad de Helsinki. Sus alumnos le decían: «Usted no nos da solo información, nos da formación». Era un buen abogado, pero vio que en esto era excelente, y dejó la abogacía para dedicarse a enseñar."}], "temperamentos": {"MEL": "Para Havard, el melancólico es idealista y creativo: crea cosas nuevas todo el tiempo. Su misión probablemente va en la dirección de las ideas.", "COL": "Para Havard, el colérico es acción y energía: sabe hacer avanzar una idea y venderla al mundo. Muchas veces crea organizaciones.", "SAN": "Para Havard, el sanguíneo es un comunicador nato: sabe reunir a la gente y convencerla de que vale la pena un proyecto.", "FLE": "Para Havard, el flemático es tranquilo y sistemático: convierte las ideas en procesos que duran años, incluso siglos."}}, {"id": "desafio", "titulo": "Mi desafío", "lecturas": [["Ya te conoces mejor: tu historia y tus talentos. Ahora mira el mundo en el que vives hoy.", "**Tu misión nace del contraste entre quién eres y lo que pasa en el mundo.**"]], "preguntas": [{"texto": "¿Cuál es el reto cultural o social al que me siento llamado a responder con pasión y determinación?", "placeholder": "¿Qué pasa en el mundo que te disgusta profundamente y contra lo que quieres luchar?", "obligatoria": true, "ejemplo": "Solzhenitsyn: el mundo del comunismo y de los campos de concentración. Madre Teresa: los más pobres entre los pobres. Lejeune: defender la vida humana con la verdad científica. Havard: la pusilanimidad, la pequeñez del ser humano en los siglos XX y XXI."}]}, {"id": "declaracion", "titulo": "Mi declaración de misión", "lecturas": [["Mi misión debe formularse de tal manera que:", "1. Destaque claramente el reto cultural o social al que respondo con pasión y determinación a través de mis acciones.", "2. Pueda cumplirla de formas muy distintas cada día.", "Havard añade: **corta**, para recordarla; **densa**, para cumplirla mil veces al día. Si no eres poeta, pide ayuda a un amigo que lo sea."]], "preguntas": [{"texto": "Escribe aquí tu declaración de misión personal.", "placeholder": "En pocas palabras.", "obligatoria": true, "contador_palabras": {"min": 3, "max": 5, "texto": "Orientación: de 3 a 5 palabras"}, "ejemplo": "Solzhenitsyn: «Quería ser la memoria de un pueblo víctima de una tragedia indecible». Lejeune: «Quería defender la verdad científica y la gran verdad moral que se deriva de ella». Madre Teresa: «Quería ser madre de los más pobres entre los pobres de la tierra». Las palabras clave son «memoria», «verdad científica», «madre»: precisas y generosas a la vez. Se puede ser madre todos los días, ser memoria todos los días, y todos los días se puede gritar una verdad científica."}]}, {"id": "organizacion", "titulo": "Mi misión y la de mi organización", "opcional": true, "lecturas": [], "preguntas": [{"texto": "Si trabajo en una empresa o en una asociación: ¿en qué medida, al cumplir la misión de mi organización, estoy cumpliendo mi misión personal?", "placeholder": "¿Tu trabajo te ayuda a cumplir tu misión o te aleja de ella?", "obligatoria": false}]}], "cierre": {"titulo": "Tu misión", "texto": "Este trabajo no termina hoy. Cada mes, tómate unas horas para reconsiderar, corregir y completar lo que has empezado. Tu misión aparecerá en «Mi perfil»."}}'::jsonb),
